  ('Sports Coaching', 12, 'G12-003', 'apply coaching skills in selected individual/dual sports through practice, observation, simulation, and feedback;', NULL, NULL, 'Coaching Exposure in Selected Individual/Dual Sports ● Coaching Practice in Selected Sports - Game play ● Participant Observation - Game Observation - Peer Observation ● Simulation - Group application - Video Analysis ● Performance Feedbacking o Debriefing o Post-evaluation'),
  ('Sports Coaching', 12, 'G12-004', 'assess the coaching performance in selected individual/dual sports;', NULL, NULL, 'Selected Sports Coaching Exposure ● Sports coaching simulation ● Types of Level of Sports Coaching (School-based, Amateur, Professional)'),
  ('Sports Coaching', 12, 'G12-005', 'explain the different characteristics of an effective team sports coach;', NULL, NULL, 'Characteristics of an Effective Coach Reflective Thinking, Good Communication Skills, Leadership and Motivation, Adaptability & Problem Solving, Goal Setting & Development Focus, Striving to Win'),
